int if_else(int x) {
  if (x) {
    return 1;
  } else {
    return 0;
  }
}

int while_loop(int x) {
  while (x) {
    break;
  }
  return x;
}

int do_while_loop(int x) {
  do {
    continue;
  } while (x);
  return x;
}

int for_loop(int x) {
  for (x; x; x) {
    break;
  }
  return x;
}

int switch_stmt(int x) {
  switch (x) {
  case 1:
    return 1;
  case 2:
    return 2;
  default:
    return 0;
  }
}

int labels_and_goto(int x) {
  goto done;
done:
  return x;
}

